from django.shortcuts import render, redirect
from django.core.mail import send_mail
from django.utils.crypto import get_random_string
from django.contrib.auth.models import User
from django.conf import settings

def reset_password_request(request):
    if request.method == 'POST':
        email = request.POST.get('email')
        try:
            user = User.objects.get(email=email)
            reset_key = get_random_string(length=32)
            user.reset_key = reset_key
            user.save()

            reset_url = f"{settings.BASE_URL}/reset-password/{reset_key}"
            send_mail(
                'Запрос на сброс пароля',
                f'Пожалуйста, перейдите по следующей ссылке для сброса пароля: {reset_url}',
                settings.EMAIL_HOST_USER,
                [email],
                fail_silently=False,
            )
            return redirect('/password-reset-sent')
        except User.DoesNotExist:
            return render(request, 'reset_password_request.html', {'error': 'Пользователь с таким email не найден'})

    return render(request, 'reset_password_request.html')

def password_reset_sent(request):
