def reset_password(request):
    if request.method == 'POST':
        new_password = request.POST.get('new_password')
        confirm_password = request.POST.get('confirm_password')
        reset_key = request.POST.get('reset_key')
        try:
            user = User.objects.get(reset_key=reset_key)
            if new_password == confirm_password:
                user.set_password(new_password)
                user.reset_key = ''
                user.save()
                return redirect('/password-reset-complete')
            else:
                return render(request, 'reset_password.html', {'error': 'Пароли не совпадают'})
        except User.DoesNotExist:
            return render(request, 'reset_password.html', {'error': 'Неверный ключ сброса'})
    return render(request, 'reset_password.html')
