```python
# models.py
from django.db import models
from django.core.exceptions import ValidationError

class Order(models.Model):
    client_id = models.CharField(max_length=255)
    total_amount = models.DecimalField(max_digits=10, decimal_places=2)
    promo_code = models.CharField(max_length=255, blank=True, null=True)

    def clean(self):
        if self.promo_code:
            existing_orders = Order.objects.filter(promo_code=self.promo_code).exclude(id=self.id)
            if existing_orders.exists():
                raise ValidationError("Each order can have only one promo code.")

    def save(self, *args, **kwargs):
        self.clean()
        super().save(*args, **kwargs)
```

2. **Проверка перед сохранением:**

